      cur = i;
      ind.style.setProperty('--t', i);
      btns.forEach((b, j) => b.classList.toggle('on', j === i));
      pns.forEach((p, j) => {
        p.style.setProperty('--o', j - i);
        p.classList.toggle('on', j === i);
