      pick(i);
    }));
    pick(0);
    const tick = () => {
      if (!root.isConnected) return;
      if (!root.dataset.paused && Date.now() > hold) pick((cur + 1) % 3);
      setTimeout(tick, 2300);
    };
    setTimeout(tick, 1300);
  }

